import{a as e,i as t,r as n,t as r}from"./app-D-qs3fho.js";var i=JSON.parse(`{"path":"/projects.html","title":"Key Projects","lang":"en-US","frontmatter":{},"git":{},"filePathRelative":"projects.md"}`),a={name:`projects.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="key-projects" tabindex="-1"><a class="header-anchor" href="#key-projects"><span>Key Projects</span></a></h1><p>A detailed overview of key professional integrations and personal projects I have engineered.</p><hr><h2 id="professional-projects-magento-2-adobe-commerce" tabindex="-1"><a class="header-anchor" href="#professional-projects-magento-2-adobe-commerce"><span>Professional Projects (Magento 2 / Adobe Commerce)</span></a></h2><h3 id="inpost-shipping-customization-module-pigunio-marketplace" tabindex="-1"><a class="header-anchor" href="#inpost-shipping-customization-module-pigunio-marketplace"><span>InPost Shipping Customization Module (Pigunio Marketplace)</span></a></h3><ul><li><strong>Description</strong>: Built a custom Magento 2 carrier-shipping module from scratch to integrate checkout shipping selectors with InPost&#39;s delivery locker API.</li><li><strong>Key Features</strong>: <ul><li>Displays dynamic shipping lockers, pick-up points, and carrier options during checkout.</li><li>Integrates third-party carrier API callbacks for address lookup.</li></ul></li></ul><h3 id="webkul-etsymagentoconnect-module-etsy-api-integration" tabindex="-1"><a class="header-anchor" href="#webkul-etsymagentoconnect-module-etsy-api-integration"><span>Webkul_EtsyMagentoConnect Module (Etsy API Integration)</span></a></h3><ul><li><strong>Description</strong>: Maintained and updated the Etsy integration module deployed on high-volume production stores.</li><li><strong>Key Features</strong>: <ul><li>Updated the API client configuration to Etsy API v3, ensuring stable synchronization.</li><li>Automated Etsy export/import processes for product listings, inventory sync, and orders.</li></ul></li></ul><h3 id="mobikul-graphql-api-modules-mobikuladminapigraphql-mobikulapigraphql" tabindex="-1"><a class="header-anchor" href="#mobikul-graphql-api-modules-mobikuladminapigraphql-mobikulapigraphql"><span>Mobikul GraphQL API Modules (<code>MobikulAdminApiGraphql</code> &amp; <code>MobikulApiGraphql</code>)</span></a></h3><ul><li><strong>Description</strong>: Authored and optimized GraphQL queries and mutations that power the Mobikul Mobile E-commerce App.</li><li><strong>Key Features</strong>: <ul><li>Engineered GraphQL schema and custom Magento 2 resolvers.</li><li>Implemented JWT-based authentication with secure <strong>refresh token</strong> functionality, preventing unexpected customer logout events.</li></ul></li></ul><hr><h2 id="professional-projects-laravel-vue-js" tabindex="-1"><a class="header-anchor" href="#professional-projects-laravel-vue-js"><span>Professional Projects (Laravel &amp; Vue.js)</span></a></h2><h3 id="alertrax-iot-asset-tracking-platform" tabindex="-1"><a class="header-anchor" href="#alertrax-iot-asset-tracking-platform"><span>AlerTrax (IoT Asset-Tracking Platform)</span></a></h3><ul><li><strong>Description</strong>: Contributed to the full-stack development of AlerTrax, a web portal and fleet tracking platform used for WiFi/LTE trailer and work-vehicle tracking.</li><li><strong>Key Features</strong>: <ul><li>Integrated <strong>Stripe API</strong> for dynamic product subscriptions (monthly/yearly tiers).</li><li>Maintained CRUD logic allowing fleet administrators to provision plans and link Stripe subscription IDs to specific hardware devices.</li><li>Developed frontend dashboard views in <strong>Vue.js</strong>.</li></ul></li></ul><h3 id="royo-e-commerce-backend-support" tabindex="-1"><a class="header-anchor" href="#royo-e-commerce-backend-support"><span>Royo (E-Commerce Backend Support)</span></a></h3><ul><li><strong>Description</strong>: Support engineer for client stores, debugging database latency and resolving custom gateway issues.</li><li><strong>Key Features</strong>: <ul><li>Integrated <strong>Stripe</strong> and <strong>CMI</strong> payment gateways.</li><li>Integrated <strong>AWS S3</strong> client wrapper to store media assets and product documents.</li></ul></li></ul><hr><h2 id="personal-projects" tabindex="-1"><a class="header-anchor" href="#personal-projects"><span>Personal Projects</span></a></h2><h3 id="real-estate-web-application-mern-stack" tabindex="-1"><a class="header-anchor" href="#real-estate-web-application-mern-stack"><span>Real Estate Web Application (MERN Stack)</span></a></h3><ul><li><strong>Tech Stack</strong>: MongoDB, Express, React, Node.js, Firebase OAuth, JWT.</li><li><strong>Features</strong>: <ul><li>Complete estate listings with search and filter parameters.</li><li>Firebase OAuth for quick login.</li><li>JWT token validation containing access &amp; refresh token rotation for secure session persistence.</li></ul></li></ul><h3 id="online-e-commerce-shopping-cart-laravel" tabindex="-1"><a class="header-anchor" href="#online-e-commerce-shopping-cart-laravel"><span>Online E-Commerce Shopping Cart (Laravel)</span></a></h3><ul><li><strong>Tech Stack</strong>: Laravel, MySQL, jQuery, AJAX.</li><li><strong>Features</strong>: <ul><li>Dynamic frontend rendering using REST endpoints and asynchronous AJAX requests.</li><li>API collection for shopping cart updates, user authentication, and product listings.</li></ul></li></ul>`,22)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};